// ---------------------------------------------------------------- shared types

// What the engine is and how it was built.
struct EngineInfo {
    std::string name = "partcraft-engine";
    // Short product version of the build (first line of version.txt), e.g. v2026.11.4.
    std::string version;
    // Full build version (second line of version.txt).
    std::string versionFull;
    // CMake build type, e.g. Release.
    std::string buildType;
    // native = separate desktop process, wasm = WebAssembly module in a worker.
    std::string platform;
    // Target, e.g. windows-x64, linux-x64, wasm32.
    std::string os;
    // Compiler and version.
    std::string compiler;
    // true when the engine was built with test commands (diagnostics.crash, diagnostics.hang).
    bool testCommands = false;
};

// Source of the bundled planegcs sketch solver.
struct PlanegcsInfo {
    // Project and release the solver sources come from, e.g. FreeCAD 1.1.4.
    std::string source;
    // Full git commit of those sources.
    std::string commit;
};

// Versions of the libraries compiled into the engine.
struct ComponentVersions {
    // Open CASCADE Technology version.
    std::string occt;
    PlanegcsInfo planegcs;
    std::string eigen;
    std::string boost;
    std::string nlohmannJson;
};

// What the transport of this engine can do.
struct Capabilities {
    // ping and cancel are answered while a command runs (native: reader thread). The WebAssembly engine answers only between commands.
    bool pingWhileBusy = false;
    // cancel reaches a running command (native always; WebAssembly only with a shared cancel flag).
    bool cancelWhileBusy = false;
};

// Message limits of this engine.
struct Limits {
    std::int64_t maxHeaderBytes = 0;
    std::int64_t maxPayloadBytes = 0;
    std::int64_t payloadAlignment = 0;
    std::int64_t maxRequestId = 0;
};

// One modelling operation of the kernel self-test with its validity and plausibility check.
struct KernelSelftestStep {
    // box, hole or fillet.
    std::string name;
    // BRepCheck_Analyzer reports the result as valid.
    bool valid = false;
    // Volume of the result in mm^3.
    double volume = 0.0;
    // Volume computed by hand (closed form) in mm^3.
    double expectedVolume = 0.0;
    std::int64_t faceCount = 0;
    std::int64_t expectedFaceCount = 0;
    std::int64_t solidCount = 0;
    double timeMs = 0.0;
    // Why the step failed; missing when it passed.
    std::optional<std::string> problem;
};

