// First command of every connection. Compares the protocol version; every other command is refused before it.
struct HelloCommand {
    static constexpr std::string_view kType = "hello";
    static constexpr bool kImmediate = true;
    static constexpr bool kTestOnly = false;
    // Protocol version the client speaks.
    std::int64_t protocol = 0;
    // Free text naming the client and its version, for diagnostics.
    std::string client;
};

// Liveness check. The native engine answers while it computes; the WebAssembly engine only between commands.
struct PingCommand {
    static constexpr std::string_view kType = "ping";
    static constexpr bool kImmediate = true;
    static constexpr bool kTestOnly = false;
};

// Cancels a queued or running command. The cancelled command answers with error code cancelled.
struct CancelCommand {
    static constexpr std::string_view kType = "cancel";
    static constexpr bool kImmediate = true;
    static constexpr bool kTestOnly = false;
    // Id of the command to cancel.
    std::int64_t target = 0;
};

// Runs after the commands queued before it, answers bye; the native engine then exits with code 0.
struct ShutdownCommand {
    static constexpr std::string_view kType = "shutdown";
    static constexpr bool kImmediate = false;
    static constexpr bool kTestOnly = false;
};

// Builds a block 80 x 50 x 20 mm with a through hole of 20 mm and a 3 mm fillet on the top hole edge, and checks every operation with BRepCheck_Analyzer plus volume and face count against closed-form values.
struct DiagnosticsKernelSelftestCommand {
    static constexpr std::string_view kType = "diagnostics.kernelSelftest";
    static constexpr bool kImmediate = false;
    static constexpr bool kTestOnly = false;
};

